recordPeaks() {
    const s = this.stats();
    this.peakPendingRgbaBytes = Math.max(this.peakPendingRgbaBytes, s.pendingRgbaBytes);
    this.peakOwnedCpuBytes = Math.max(this.peakOwnedCpuBytes, s.ownedCpuBytes);
    this.peakOwnedGpuBytes = Math.max(this.peakOwnedGpuBytes, s.ownedGpuBytes);
    this.peakRetiredGpuBytes = Math.max(this.peakRetiredGpuBytes, s.retiredGpuBytes);
